mapper.select:
SELECT p.*, , s.name AS shop_name, s.rating AS shop_rating, s.logo AS shop_logo FROM products AS p
INNER JOIN shops AS s ON p.shop_id = s.id AND s.status = 'open' AND s.archived_at IS NULL INNER JOIN users AS owner ON owner.id = s.owner_id AND owner.status = 'normal' WHERE p.status = 'on' AND p.product_type = 'goods'
AND p.shop_id = #{shopId}
AND (pc.category_code = #{categoryFilter} OR parent.category_code = #{categoryFilter} OR pc.category_name = #{categoryFilter} OR parent.category_name = #{categoryFilter})
AND (p.name LIKE CONCAT(#{keyword}, '%') OR p.description LIKE CONCAT(#{keyword}, '%') OR s.name LIKE CONCAT(#{keyword}, '%'))
ORDER BY p.created_at DESC LIMIT #{offset}, #{limit}

SELECT p.*, ,
       s.name AS shop_name, s.rating AS shop_rating, s.logo AS shop_logo
FROM products AS p

LEFT JOIN shops AS s ON p.shop_id = s.id
WHERE p.shop_id = #{shopId}

    AND p.name LIKE CONCAT(#{keyword}, '%')


    AND (pc.category_code = #{categoryFilter}
         OR parent.category_code = #{categoryFilter}
         OR pc.category_name = #{categoryFilter}
         OR parent.category_name = #{categoryFilter})


    AND p.status = #{status}


    AND p.stock <= #{stockMax}


    AND p.product_type = #{productType}



        ORDER BY p.stock ASC, p.created_at DESC


        ORDER BY p.created_at DESC


LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM products AS p
INNER JOIN product_categories AS pc ON pc.id = p.category_id
LEFT JOIN product_categories AS parent ON parent.id = pc.parent_id
WHERE p.shop_id = #{shopId}

    AND p.name LIKE CONCAT(#{keyword}, '%')


    AND (pc.category_code = #{categoryFilter}
         OR parent.category_code = #{categoryFilter}
         OR pc.category_name = #{categoryFilter}
         OR parent.category_name = #{categoryFilter})


    AND p.status = #{status}


    AND p.stock <= #{stockMax}


    AND p.product_type = #{productType}

SELECT p.*, ,
       s.name AS shop_name, s.rating AS shop_rating, s.logo AS shop_logo
