SELECT COUNT(*)
FROM products AS p
INNER JOIN product_categories AS pc ON pc.id = p.category_id
LEFT JOIN product_categories AS parent ON parent.id = pc.parent_id
INNER JOIN shops AS s ON p.shop_id = s.id
WHERE s.owner_id = #{ownerId}
  AND s.archived_at IS NULL
