SELECT p.*, ,
       s.name AS shop_name, s.rating AS shop_rating, s.logo AS shop_logo
FROM products AS p

LEFT JOIN shops AS s ON p.shop_id = s.id
WHERE 1=1

    AND p.name LIKE CONCAT(#{keyword}, '%')


    AND p.status = #{status}


    AND p.product_type = #{productType}

