SELECT COUNT(*) FROM products AS p INNER JOIN product_categories AS pc ON pc.id = p.category_id LEFT JOIN product_categories AS parent ON parent.id = pc.parent_id WHERE 1=1
AND p.name LIKE CONCAT(#{keyword}, '%')
AND p.status = #{status}
AND p.product_type = #{productType}

