SELECT EXISTS(
    SELECT 1 FROM order_appointment_slots AS oas
    JOIN appointment_slots AS s ON s.id = oas.slot_id
    WHERE s.service_id = #{serviceId}
)

mapper.update:
UPDATE products
SET status = CASE WHEN stock - #{quantity} <= 0 THEN 'off' ELSE status END,
    stock = stock - #{quantity}
WHERE id = #{productId}
  AND product_type = 'goods'
  AND status = 'on'
  AND stock >= #{quantity}

UPDATE products
SET stock = stock + #{quantity}
WHERE id = #{productId}
  AND product_type = 'goods'

